param(
    [string] $OutputPath = "unity/JabaSurvivol/Assets/_Project/Scripts/Generated/BuildInfo.g.cs"
)

$commit = (git rev-parse --short HEAD).Trim()
$branch = (git rev-parse --abbrev-ref HEAD).Trim()
$version = (git describe --tags --always --dirty).Trim()
$generatedAt = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")

$directory = Split-Path -Parent $OutputPath
if (-not [string]::IsNullOrWhiteSpace($directory)) {
    New-Item -ItemType Directory -Force -Path $directory | Out-Null
}

$content = @"
// <auto-generated />
namespace JabaSurvivol.Build
{
    public static class BuildInfo
    {
        public const string Version = "$version";
        public const string Commit = "$commit";
        public const string Branch = "$branch";
        public const string GeneratedAtUtc = "$generatedAt";
    }
}
"@

[System.IO.File]::WriteAllText((Resolve-Path -LiteralPath ".").Path + [System.IO.Path]::DirectorySeparatorChar + $OutputPath, $content)
Write-Output "Wrote build info to $OutputPath."
